{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Evidence-led wellness coaching focused on habits, frameworks, and sustainable outcomes. Join the membership for weekly guidance and measurable progress.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="site-root">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Main navigation">
        <ul>
          <li><a href="index.html">Home</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="programs.html">Paths</a></li>
          <li><a href="pricing.html">Plans</a></li>
          <li><a href="testimonials.html">Stories</a></li>
          <li><a href="book.html">Book</a></li>
          <li><a href="contact.html">Contact</a></li>
        </ul>
      </nav>
      <button class="cta" onclick="location.href='{{PRIMARY_CTA_URL}}'">{{PRIMARY_CTA_LABEL}}</button>
      <button id="navToggle" class="nav-toggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-content">
          <h1 class="hero-title">Measured change, steady momentum.</h1>
          <p class="hero-lead">I combine small, evidence-based habit frameworks with human-centered coaching to create sustainable health and resilience. No extremes — just repeatable systems that fit your life.</p>
          <p class="hero-meta">Led by {{COACH_NAME}}, {{CREDENTIALS}} — based in {{CITY}}, {{STATE}}.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="link" href="programs.html">Explore Paths</a>
          </div>
          <p class="lead-magnet">Free guide: "5 Daily Signals That Predict Sustainable Progress" — delivered when you book a discovery session.</p>
        </div>
        <div class="hero-visual">
          <img src="assets/img/hero.svg" alt="Abstract graphic representing balance and rhythm" width="420" height="280">
        </div>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section class="myth-truth">
      <div class="wrap">
        <h2 class="section-title">Myths, tested — truths, clarified</h2>
        <div class="mt-grid">
          <div class="mt-card">
            <h3>Myth: Quick fixes produce lasting results</h3>
            <p>Truth: Short-term tactics often fail without habit scaffolding. We design compact experiments that build repeatable behaviors over weeks, not days.</p>
          </div>
          <div class="mt-card">
            <h3>Myth: Motivation is the only driver</h3>
            <p>Truth: Systems and environmental cues double the likelihood of consistent action. We map triggers, micro-actions, and recovery plans.</p>
          </div>
          <div class="mt-card">
            <h3>Myth: One-size programs fit all</h3>
            <p>Truth: Context matters. Our membership adapts based on habits, feedback data, and real-world constraints.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PILLARS -->
    <section class="pillars">
      <div class="wrap">
        <h2 class="section-title">Three pillars of progress</h2>
        <div class="pillars-grid">
          <div class="pillar">
            <img src="assets/img/pattern.svg" alt="icon: framework" class="pillar-ill">
            <h3>Micro-frameworks</h3>
            <p>Simple routines designed to be repeated. Each framework has checkpoints and a lightweight tracking method.</p>
          </div>
          <div class="pillar">
            <img src="assets/img/avatar.svg" alt="icon: coaching" class="pillar-ill">
            <h3>Guided feedback</h3>
            <p>Bi-weekly coaching cycles that prioritize problem-solving and adjustment over motivation talks.</p>
          </div>
          <div class="pillar">
            <img src="assets/img/hero.svg" alt="icon: outcomes" class="pillar-ill small">
            <h3>Outcome-focused metrics</h3>
            <p>We track behaviors that predict outcomes (sleep rhythm, movement consistency, stress buffers) and use them to adjust plans.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- CASE STUDIES -->
    <section class="case-studies">
      <div class="wrap">
        <h2 class="section-title">Short case studies — measurable shifts</h2>
        <p class="section-lead">Evidence-driven coaching with documented habit adoption and quality-of-life improvements.</p>
        <div class="cs-list">
          <article class="case">
            <h3>Engineer to Energized</h3>
            <p>Problem: Irregular sleep and poor recovery. Intervention: 6-week circadian-friendly routine. Outcome: 45 minutes earlier core sleep time and fewer night awakenings reported.</p>
          </article>
          <article class="case">
            <h3>Manager regains margins</h3>
            <p>Problem: Chronic schedule overload. Intervention: Time-buffer framework and decision triage. Outcome: 3 fewer evening work hours and improved focus during deep tasks.</p>
          </article>
          <article class="case">
            <h3>New parent, steady baseline</h3>
            <p>Problem: Fragmented routine. Intervention: Micro-rest protocol and short anchor rituals. Outcome: Better mood stability and more consistent naps for baby, reducing nighttime stress.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq">
      <div class="wrap">
        <h2 class="section-title">Questions I hear most</h2>
        <div class="faq-grid">
          <button class="faq-item" aria-expanded="false">
            <span class="q">How does the membership differ from a one-off program?</span>
            <span class="a">Membership emphasizes iterative adjustments and community cues — weekly micro-tasks, monthly checkpoints, and on-demand coaching to maintain momentum.</span>
          </button>
          <button class="faq-item" aria-expanded="false">
            <span class="q">Will you prescribe diets or medications?</span>
            <span class="a">No. Coaching focuses on habits, environment, and behavior change. Any medical or dietary prescriptions are referred to appropriate professionals.</span>
          </button>
          <button class="faq-item" aria-expanded="false">
            <span class="q">What if I don’t have time for coaching?</span>
            <span class="a">Most plans are built on micro-actions (5–15 minutes). We tailor interventions to real schedules and prioritize highest-leverage behaviors.</span>
          </button>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta-strip">
      <div class="wrap cta-inner">
        <div>
          <h2>Start with a clear signal — not a big promise</h2>
          <p>Book a discovery call to receive the free guide and a snapshot habit audit. You’ll leave with one concrete, measurable step you can implement tomorrow.</p>
        </div>
        <div>
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">Book a discovery — {{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
        <p><a href="tel:{{PHONE}}">{{PHONE}}</a> · <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <nav>
        <ul>
          <li><a href="about.html">About</a></li>
          <li><a href="services.html">Services</a></li>
          <li><a href="programs.html">Programs</a></li>
          <li><a href="pricing.html">Pricing</a></li>
        </ul>
      </nav>
      <div class="credits">© <span id="year"></span> {{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}}</div>
    </div>
  </footer>

</body>
</html>"} 
