{"path":"assets/css/styles.css","content":"/* Minimal, zen-inspired stylesheet */
:root{
  --bg:#fbfcfd; --text:#0b1116; --muted:#6b7380; --accent:#0b7a5f; --soft:#eef6f2; --maxw:1100px;
  --radius:10px; --gap:28px; --wrap-padding:24px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial; margin:0; background:var(--bg); color:var(--text); -webkit-font-smoothing:antialiased}
.wrap{max-width:var(--maxw); margin:0 auto; padding:36px var(--wrap-padding)}
.site-header{background:transparent; position:sticky; top:0; z-index:30; backdrop-filter:blur(4px)}
.site-header .wrap{display:flex; align-items:center; gap:16px}
.brand{font-weight:700; text-decoration:none; color:var(--text); font-size:18px}
.main-nav ul{list-style:none; display:flex; gap:18px; margin:0; padding:0}
.main-nav a{color:var(--muted); text-decoration:none}
.nav-toggle{display:none; background:none; border:0; font-size:20px}
.cta{background:transparent; border:1px solid var(--accent); color:var(--accent); padding:8px 12px; border-radius:8px}
.hero{padding:56px 0}
.hero-grid{display:grid; grid-template-columns:1fr 420px; gap:var(--gap); align-items:center}
.hero-title{font-size:32px; margin:0 0 12px}
.hero-lead{color:var(--muted); margin:0 0 16px}
.hero-meta{font-size:13px; color:var(--muted); margin-bottom:18px}
.hero-actions{display:flex; gap:12px; align-items:center}
.btn{display:inline-block; padding:10px 16px; border-radius:10px; text-decoration:none; font-weight:600}
.btn.primary{background:var(--accent); color:#fff}
.btn.primary.large{padding:14px 20px}
.lead-magnet{font-size:13px; color:var(--muted); margin-top:12px}
.hero-visual img{width:100%; height:auto; display:block}
.section-title{font-size:20px; margin:0 0 14px}
.myth-truth{padding:40px 0}
.mt-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:18px}
.mt-card{background:#fff; border-radius:10px; padding:18px; box-shadow:0 6px 18px rgba(12,18,20,0.04)}
.pillars{padding:40px 0}
.pillars-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:18px}
.pillar{background:#fff; padding:20px; border-radius:10px; text-align:left}
.pillar-ill{height:56px; width:56px; display:block; margin-bottom:12px}
.case-studies{padding:40px 0}
.cs-list{display:grid; gap:12px}
.case{background:#fff; padding:16px; border-radius:8px}
.faq{padding:40px 0}
.faq-grid{display:grid; gap:8px}
.faq-item{background:#fff; border:0; padding:14px; text-align:left; border-radius:8px; cursor:pointer}
.faq-item .q{font-weight:600}
.faq-item .a{display:none; margin-top:8px; color:var(--muted)}
.faq-item[aria-expanded="true"] .a{display:block}
.cta-strip{background:linear-gradient(90deg, #f7fbf9, #ffffff); padding:32px 0}
.cta-inner{display:flex; justify-content:space-between; align-items:center; gap:20px}
.site-footer{border-top:1px solid #eaeef0; padding:24px 0}
.footer-grid{display:grid; grid-template-columns:1fr 1fr auto; gap:16px; align-items:center}
.footer-grid a{color:var(--muted); text-decoration:none}
.credits{color:var(--muted); font-size:13px}
/* Responsive */
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr;}
  .mt-grid{grid-template-columns:1fr}
  .pillars-grid{grid-template-columns:1fr}
  .wrap{padding:28px 20px}
  .main-nav{display:none}
  .nav-toggle{display:block}
}
"} 
{"path":"assets/js/main.js","content":"// Minimal interactive behaviors: nav toggle, FAQ accordion, year fill
document.addEventListener('DOMContentLoaded',function(){
  var navToggle = document.getElementById('navToggle');
  var nav = document.querySelector('.main-nav');
  if(navToggle){
    navToggle.addEventListener('click',function(){
      if(nav.style.display==='block'){nav.style.display=''}else{nav.style.display='block'}
    });
  }

  var faqs = Array.from(document.querySelectorAll('.faq-item'));
  faqs.forEach(function(btn){
    btn.addEventListener('click',function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      faqs.forEach(function(b){b.setAttribute('aria-expanded','false')});
      this.setAttribute('aria-expanded', String(!expanded));
    });
  });

  var y = document.getElementById('year');
  if(y){ y.textContent = new Date().getFullYear(); }

  // Light smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var t = document.querySelector(this.getAttribute('href'));
      if(t){ e.preventDefault(); t.scrollIntoView({behavior:'smooth'}); }
    });
  });
});"} 
